selam su koda baksana okul kermesi gonullu listesi icin yazmistm ne yapiyo tam ozet gecermsn

def slot_sayisi(kayitlar):
    ozet = {}
    for ad, gorev in kayitlar:
        ozet[gorev] = ozet.get(gorev, 0) + 1
    return ozet

su koda bi bakar msn ne yapiyo tam olark anlamadm:

def sayac(ziyaretler):
    sonuc = {}
    for sehir, alim in ziyaretler:
        if sehir not in sonuc:
            sonuc[sehir] = set()
        sonuc[sehir].add(alim)
    return {k: len(v) for k, v in sonuc.items()}

